def rects_for_text(page, text):
    """Robustly locate all rects for `text` on `page`, trying variants and
    sub-token splits (handles multi-line / hyphenated matches)."""
    if not text:
        return []
    seen = set()
    rects = []

    def _add(rs):
        for r in rs:
            key = (round(r.x0, 1), round(r.y0, 1), round(r.x1, 1), round(r.y1, 1))
            if key not in seen:
                seen.add(key)
                rects.append(r)

    # 1. direct search
    try:
        _add(page.search_for(text, quads=False))
    except Exception:
        pass

    nv = norm_space(text)
    if nv and nv != text:
        try:
            _add(page.search_for(nv, quads=False))
        except Exception:
            pass

    stripped = text.strip(" .,:;()[]{}")
    if stripped and stripped != text:
        try:
            _add(page.search_for(stripped, quads=False))
        except Exception:
            pass

    if rects:
        return rects

    # 2. split on hyphens / slashes / whitespace to catch line-wrapped matches
    #    (useful for grant numbers like W911NF-23-2-\n0224)
    sub_parts = [p for p in re.split(r"[\s\-/]+", stripped) if len(p) >= 4]
    for sp in sub_parts:
        try:
            _add(page.search_for(sp, quads=False))
        except Exception:
            pass
    if rects:
        return rects

    # 3. last resort: longest contiguous word sub-sequence
    toks = stripped.split()
    for n in range(len(toks), 1, -1):
        for i in range(len(toks) - n + 1):
            sub = " ".join(toks[i:i + n])
            try:
                r = page.search_for(sub, quads=False)
            except Exception:
                r = []
            if r:
                _add(r)
                return rects
    return rects


def find_references_page(doc):
    for i, pg in enumerate(doc):
        text = pg.get_text()
        for header in ("References", "REFERENCES", "Bibliography", "BIBLIOGRAPHY"):
            if re.search(rf"(?m)^\s*(?:\d+\.?\s*)?{header}\s*$", text):
                return i
            # fallback: header appears somewhere
            if header in text:
                # confirm visually by searching
                rs = pg.search_for(header)
                if rs:
                    return i
    return None


def apply_redactions_page(page, literals, regexes, use_literals):
    added = 0
    if use_literals:
        for lit in sorted(literals, key=len, reverse=True):
            for rect in rects_for_text(page, lit):
                page.add_redact_annot(rect, fill=(0, 0, 0))
                added += 1
    text = page.get_text()
    for rx in regexes:
        for m in rx.finditer(text):
            for r in rects_for_text(page, m.group(0)):
                page.add_redact_annot(r, fill=(0, 0, 0))
                added += 1
    if added:
        page.apply_redactions()
    return added


def scan_leaks(doc, literals, regexes, ref_idx):
    leaks = []
    for i, pg in enumerate(doc):
        text = pg.get_text()
        for rx in regexes:
            for m in rx.finditer(text):
                leaks.append((i, "regex", m.group(0)))
        if ref_idx is None or i < ref_idx:
            for lit in literals:
                if lit and lit in text:
                    leaks.append((i, "literal", lit))
    return leaks


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def redact_pdf(src: Path, dst: Path):
    doc = fitz.open(src)
    orig_pages = len(doc)
    orig_text_len = sum(len(p.get_text()) for p in doc)
    literals = discover_identity(doc)
    ref_idx = find_references_page(doc)
    print(f"[{src.name}] {orig_pages} pages, references at page {ref_idx}, "
          f"{len(literals)} identity literals")
    for lit in sorted(literals):
        print(f"    LIT :: {lit!r}")

    for attempt in range(3):
        for i, pg in enumerate(doc):
            use_literals = (ref_idx is None) or (i < ref_idx)
            apply_redactions_page(pg, literals, IDENTIFIER_PATTERNS, use_literals)
        doc.set_metadata({})
        try:
            doc.set_xml_metadata("")
        except Exception:
            pass
        doc.save(dst, garbage=4, deflate=True, clean=True)
        doc.close()

        verify = fitz.open(dst)
        leaks = scan_leaks(verify, literals, IDENTIFIER_PATTERNS, ref_idx)
        if not leaks:
            assert len(verify) == orig_pages, "page count changed"
            retained = sum(len(p.get_text()) for p in verify) / max(orig_text_len, 1)
            print(f"[{src.name}] clean after iteration {attempt + 1}, "
                  f"text retained {retained:.1%}")
            verify.close()
            return
        print(f"[{src.name}] iteration {attempt + 1}: {len(leaks)} leaks remain")
        for p, k, m in leaks[:30]:
            print(f"    LEAK page {p} ({k}): {m!r}")
        doc = verify
    raise RuntimeError(f"{src.name}: leaks remain after 3 iterations")


def main():
    out = Path("/root/redacted")
    out.mkdir(parents=True, exist_ok=True)
    for n in (1, 2, 3):
        print("=" * 80)
        redact_pdf(Path(f"/root/paper{n}.pdf"), out / f"paper{n}.pdf")


if __name__ == "__main__":
    main()
