NAME_TOKEN_RE = re.compile(r"[A-Z][\w’'\-]+")


def looks_like_name(tok: str) -> bool:
    """Heuristic: a candidate author name is 2-5 capitalized tokens."""
    parts = tok.split()
    if not (2 <= len(parts) <= 5):
        return False
    for p in parts:
        if not p:
            return False
        # middle initial like "P." allowed
        if re.fullmatch(r"[A-Z]\.", p):
            continue
        if not (p[0].isupper() or p[0] in "“\"'"):
            return False
        if not re.fullmatch(r"[A-Z][\w’'\-\.\"“”]*", p):
            return False
    return True


def extract_author_names(line: str):
    s = re.sub(r"\s+and\s+", ", ", line, flags=re.IGNORECASE)
    out = []
    for part in re.split(r"[,;]", s):
        n = strip_marks(part)
        if looks_like_name(n):
            out.append(n)
    return out


AFFIL_KEYWORDS = (
    "University", "Institute", "Laboratory", "Lab", "College", "School",
    "Corporation", "Research", "Center", "Centre", "Department",
    "Academy", "Hospital", "Foundation", "Community",
)


def extract_affiliations(text: str):
    """Return a set of affiliation strings found in text."""
    out = set()
    # Try to split by comma, semicolon, newline, and digit/star markers.
    # Replace leading markers with newlines so each affiliation stands alone.
    s = re.sub(rf"(?:(?<=[\s,;])|^)[\s{re.escape(AUTHOR_MARK_CHARS)}\d]+(?=[A-Z])",
               "\n", text)
    for piece in re.split(r"[\n;]", s):
        piece = piece.strip(" ,;.")
        if not piece:
            continue
        # cut piece at next affiliation-starting marker
        # if any affiliation keyword present
        if any(kw in piece for kw in AFFIL_KEYWORDS):
            # keep up to the keyword + possibly a comma-chunk
            # Save the whole piece plus the shorter form "X University"/"X Institute"
            out.add(piece)
            # also pull "<Something> University of X" / "<Something> Institute" phrases
            for m in re.finditer(
                r"[A-Z][\w\.\-&]*(?:\s+[A-Z][\w\.\-&]*){0,6}\s+(?:"
                + "|".join(AFFIL_KEYWORDS)
                + r")(?:\s+of\s+[A-Z][\w\.\-&]*(?:\s+[A-Z][\w\.\-&]*){0,4})?",
                piece,
            ):
                out.add(m.group(0).strip(" ,;."))
    return out


# ---------------------------------------------------------------------------
# Page-1 identity discovery
# ---------------------------------------------------------------------------
def find_abstract_y(page):
    for b in page.get_text("blocks"):
        x0, y0, x1, y1, txt, bno, btype = b
        t = txt.strip().lower()
        if t == "abstract" or t.startswith("abstract\n") or t.startswith("a b s t r a c t"):
            return y0
    for word in ("Abstract", "ABSTRACT"):
        rs = page.search_for(word)
        if rs:
            return rs[0].y0
    return None


def is_author_block(text: str) -> bool:
    """Heuristic: text block containing author markers (digits/stars after names)."""
    # Must have at least 2 capitalized name-like tokens AND author markers nearby
    if not re.search(r"[A-Z][a-z]+\s+[A-Z][a-z]+", text):
        return False
    if re.search(rf"[A-Za-z][{re.escape(AUTHOR_MARK_CHARS)}]", text):
        return True
    if re.search(r"[A-Za-z]\d(?:[,\s]|$)", text):
        return True
    if re.search(r"\sand\s", text, flags=re.IGNORECASE) and "," in text:
        return True
    return False


def is_affiliation_block(text: str) -> bool:
    return any(kw in text for kw in AFFIL_KEYWORDS)


def is_footnote_block(text: str) -> bool:
    low = text.lower()
    if any(kw in low for kw in (
        "equal contribution", "corresponding author", "correspondence",
        "copyright", "supported by", "supported in part",
        "preprint", "under review", "to appear",
    )):
        return True
    if "@" in text:
        return True
    # starts with footnote marker
    if re.match(rf"^\s*[{re.escape(AUTHOR_MARK_CHARS)}]", text):
        return True
    # typical venue line
    if re.search(r"(workshop|conference|proceedings|arxiv|preprint)", low):
        return True
    return False


VENUE_RE = re.compile(
    r"\b(?:Proceedings|Proc\.?|Workshop|Conference|Journal|Transactions|"
    r"ICML|NeurIPS|NIPS|ICLR|ACL|EMNLP|NAACL|CVPR|ICCV|ECCV|AAAI|IJCAI|"
    r"SIGGRAPH|Interspeech|ICASSP|TASLP|AISTATS|KDD|WWW|SIGIR|UAI|COLT|JMLR)\b"
    r"[^\n\.]{0,120}", re.IGNORECASE)


def discover_identity(doc):
    literals = set()
    page1 = doc[0]
    abs_y = find_abstract_y(page1) or page1.rect.height * 0.3
    ph = page1.rect.height

    # Partition page-1 blocks
    all_blocks = []
    for b in page1.get_text("blocks"):
        x0, y0, x1, y1, txt, bno, btype = b
        t = txt.strip()
        if t:
            all_blocks.append((y0, y1, t))
    all_blocks.sort()

    pre_abs = [b for b in all_blocks if b[1] <= abs_y + 2]
    post_abs = [b for b in all_blocks if b[0] > abs_y + 2]

    # 1. From pre-abstract blocks: identify author / affiliation blocks
    for y0, y1, t in pre_abs:
        if is_author_block(t):
            for name in extract_author_names(t):
                literals.add(name)
        if is_affiliation_block(t):
            literals.update(extract_affiliations(t))

    # 2. From post-abstract blocks on page 1: identify footnote blocks and
    #    extract emails, affiliations, grants, venue strings. We also save
    #    specific identity-bearing text snippets.
    for y0, y1, t in post_abs:
        if not is_footnote_block(t):
            continue
        # Pull out emails as literals (regex covers them too, but belt-and-braces)
        for m in re.finditer(r"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}", t):
            literals.add(m.group(0))
        # Pull out affiliations
        literals.update(extract_affiliations(t))
        # Pull out author names (for correspondence lines)
        for name in extract_author_names(t):
            literals.add(name)
        # Pull out venue phrases
        for m in VENUE_RE.finditer(t):
            v = m.group(0).strip(" ,;.")
            if len(v) >= 6:
                literals.add(v)
        # Pull out "Copyright YYYY by the author(s)" style lines
        for m in re.finditer(r"Copyright\s+\d{4}[^\n]*", t):
            literals.add(m.group(0).strip(" .,;"))

    # 3. From metadata
    md = doc.metadata or {}
    for key in ("author", "subject", "keywords", "title"):
        v = md.get(key) or ""
        if not v:
            continue
        if key == "author":
            for part in re.split(r"[;,]", v):
                n = strip_marks(part)
                if looks_like_name(n):
                    literals.add(n)
        elif key == "subject":
            # subject may contain venue (e.g. "Proceedings of ... ICML 2025")
            for m in VENUE_RE.finditer(v):
                literals.add(m.group(0).strip(" ,;."))

    # 4. Repeated top/bottom header/footer bands — only if they contain an
    #    identity signal (email, affiliation keyword, or an author name).
    def is_identity_header(s):
        if "@" in s:
            return True
        if any(kw in s for kw in AFFIL_KEYWORDS):
            return True
        for lit in literals:
            if len(lit.split()) >= 2 and lit in s:
                return True
        return False

    tops, bots = {}, {}
    for i, pg in enumerate(doc):
        h = pg.rect.height
        for b in pg.get_text("blocks"):
            x0, y0, x1, y1, txt, bno, btype = b
            t = txt.strip()
            if not t:
                continue
            if y1 < 60:
                tops.setdefault(t, []).append(i)
            if y0 > h - 60:
                bots.setdefault(t, []).append(i)
    for d in (tops, bots):
        for k, v in d.items():
            if len(v) >= 2 and is_identity_header(k):
                literals.add(k)

    # 5. Clean up literals: drop short, numeric-only, or extremely generic entries.
    GENERIC = {"abstract", "preprint", "introduction", "equal contribution",
               "corresponding author", "the author", "the authors",
               "author", "authors"}
    cleaned = set()
    for lit in literals:
        s = lit.strip()
        if len(s) < 3:
            continue
        if s.isdigit():
            continue
        if s.lower() in GENERIC:
            continue
        if not any(c.isalpha() for c in s):
            continue
        cleaned.add(s)
    return cleaned


# ---------------------------------------------------------------------------
# Redaction helpers
# ---------------------------------------------------------------------------
def rects_for_text(page, text):
    """Robustly locate all rects for `text` on `page`, trying variants and
    sub-token splits (handles multi-line / hyphenated matches)."""
    if not text:
        return []
    seen = set()
    rects = []

    def _add(rs):
        for r in rs:
            key = (round(r.x0, 1), round(r.y0, 1), round(r.x1, 1), round(r.y1, 1))
            if key not in seen:
                seen.add(key)
                rects.append(r)

    # 1. direct search
    try:
        _add(page.search_for(text, quads=False))
    except Exception:
        pass

    nv = norm_space(text)
    if nv and nv != text:
        try:
            _add(page.search_for(nv, quads=False))
        except Exception:
            pass

    stripped = text.strip(" .,:;()[]{}")
    if stripped and stripped != text:
        try:
            _add(page.search_for(stripped, quads=False))
        except Exception:
            pass

    if rects:
        return rects

    # 2. split on hyphens / slashes / whitespace to catch line-wrapped matches
    #    (useful for grant numbers like W911NF-23-2-\n0224)
    sub_parts = [p for p in re.split(r"[\s\-/]+", stripped) if len(p) >= 4]
    for sp in sub_parts:
        try:
            _add(page.search_for(sp, quads=False))
        except Exception:
            pass
    if rects:
        return rects

    # 3. last resort: longest contiguous word sub-sequence
    toks = stripped.split()
    for n in range(len(toks), 1, -1):
        for i in range(len(toks) - n + 1):
            sub = " ".join(toks[i:i + n])
            try:
                r = page.search_for(sub, quads=False)
            except Exception:
                r = []
            if r:
                _add(r)
                return rects
    return rects


def find_references_page(doc):
    for i, pg in enumerate(doc):
        text = pg.get_text()
        for header in ("References", "REFERENCES", "Bibliography", "BIBLIOGRAPHY"):
            if re.search(rf"(?m)^\s*(?:\d+\.?\s*)?{header}\s*$", text):
                return i
            # fallback: header appears somewhere
            if header in text:
                # confirm visually by searching
                rs = pg.search_for(header)
                if rs:
                    return i
    return None


def apply_redactions_page(page, literals, regexes, use_literals):
    added = 0
    if use_literals:
        for lit in sorted(literals, key=len, reverse=True):
            for rect in rects_for_text(page, lit):
                page.add_redact_annot(rect, fill=(0, 0, 0))
                added += 1
    text = page.get_text()
    for rx in regexes:
        for m in rx.finditer(text):
            for r in rects_for_text(page, m.group(0)):
                page.add_redact_annot(r, fill=(0, 0, 0))
                added += 1
    if added:
        page.apply_redactions()
    return added


def scan_leaks(doc, literals, regexes, ref_idx):
    leaks = []
    for i, pg in enumerate(doc):
        text = pg.get_text()
        for rx in regexes:
            for m in rx.finditer(text):
                leaks.append((i, "regex", m.group(0)))
        if ref_idx is None or i < ref_idx:
            for lit in literals:
                if lit and lit in text:
                    leaks.append((i, "literal", lit))
    return leaks


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def redact_pdf(src: Path, dst: Path):
    doc = fitz.open(src)
    orig_pages = len(doc)
    orig_text_len = sum(len(p.get_text()) for p in doc)
    literals = discover_identity(doc)
    ref_idx = find_references_page(doc)
    print(f"[{src.name}] {orig_pages} pages, references at page {ref_idx}, "
          f"{len(literals)} identity literals")
    for lit in sorted(literals):
        print(f"    LIT :: {lit!r}")

    for attempt in range(3):
        for i, pg in enumerate(doc):
            use_literals = (ref_idx is None) or (i < ref_idx)
            apply_redactions_page(pg, literals, IDENTIFIER_PATTERNS, use_literals)
        doc.set_metadata({})
        try:
            doc.set_xml_metadata("")
        except Exception:
            pass
        doc.save(dst, garbage=4, deflate=True, clean=True)
        doc.close()

        verify = fitz.open(dst)
        leaks = scan_leaks(verify, literals, IDENTIFIER_PATTERNS, ref_idx)
        if not leaks:
            assert len(verify) == orig_pages, "page count changed"
            retained = sum(len(p.get_text()) for p in verify) / max(orig_text_len, 1)
            print(f"[{src.name}] clean after iteration {attempt + 1}, "
                  f"text retained {retained:.1%}")
            verify.close()
            return
        print(f"[{src.name}] iteration {attempt + 1}: {len(leaks)} leaks remain")
        for p, k, m in leaks[:30]:
            print(f"    LEAK page {p} ({k}): {m!r}")
        doc = verify
    raise RuntimeError(f"{src.name}: leaks remain after 3 iterations")


def main():
    out = Path("/root/redacted")
    out.mkdir(parents=True, exist_ok=True)
    for n in (1, 2, 3):
        print("=" * 80)
        redact_pdf(Path(f"/root/paper{n}.pdf"), out / f"paper{n}.pdf")


if __name__ == "__main__":
    main()
