        line = line.strip(" ,;")
        if len(line) >= 4 and any(c.isalpha() for c in line):
            out.add(line)
    return out


# ---------------------------------------------------------------------------
# Discovery
# ---------------------------------------------------------------------------
def find_abstract_y(page):
    """Return y-coordinate where the 'Abstract' header begins, or None."""
    for b in page.get_text("blocks"):
        x0, y0, x1, y1, txt, bno, btype = b
        t = txt.strip().lower()
        if t == "abstract" or t.startswith("abstract\n") or t == "abstract.":
            return y0
    # fallback: search_for
    for word in ("Abstract", "ABSTRACT"):
        rs = page.search_for(word)
        if rs:
            return rs[0].y0
    return None


def discover_identity(doc):
    """Return (identity_literals, debug) discovered from this document."""
    literals = set()

    page1 = doc[0]
    abs_y = find_abstract_y(page1) or page1.rect.height * 0.3

    # --- title block: everything above Abstract (excluding the main title line)
    title_blocks = []
    for b in page1.get_text("blocks"):
        x0, y0, x1, y1, txt, bno, btype = b
        if y1 <= abs_y and txt.strip():
            title_blocks.append((y0, txt.strip()))
    title_blocks.sort()

    # Heuristic: first block is the title (keep), remainder = author/affiliation/correspondence
    for i, (y, t) in enumerate(title_blocks):
        if i == 0:
            # usually the title; skip
            continue
        # split lines
        for line in t.splitlines():
            line = line.strip()
            if not line:
                continue
            # whole raw line as a literal (useful for correspondence/affiliation lines)
            literals.add(line)
            # try to extract author names
            if any(ch.isdigit() or ch in "♠♣♥♦†‡§¶*⋆∗" for ch in line) or ("," in line and len(line.split()) <= 40):
                for name in split_authors(line):
                    literals.add(name)
            # affiliations
            for aff in split_affiliations(line):
                literals.add(aff)

    # --- also extract footnote / correspondence block near bottom of page 1
    # (equal contribution / affiliation / grant / venue footnote)
    ph = page1.rect.height
    for b in page1.get_text("blocks"):
        x0, y0, x1, y1, txt, bno, btype = b
        if y0 > ph * 0.75 and txt.strip():
            for line in txt.splitlines():
                line = line.strip()
                if not line or line.isdigit():
                    continue
                literals.add(line)
                # also extract names if any
                for name in split_authors(line):
                    literals.add(name)
                for aff in split_affiliations(line):
                    literals.add(aff)

    # --- metadata author/subject/title fields
    md = doc.metadata or {}
    for key in ("author", "subject", "keywords"):
        v = md.get(key) or ""
        if not v:
            continue
        # author field may be semicolon- or comma-separated
        for part in re.split(r"[;,]", v):
            n = strip_marks(part)
            if len(n.split()) >= 2:
                literals.add(n)
        # also keep the whole string
        literals.add(v.strip())

    # --- repeated header/footer bands containing author-looking tokens
    tops, bots = {}, {}
    for i, pg in enumerate(doc):
        h = pg.rect.height
        for b in pg.get_text("blocks"):
            x0, y0, x1, y1, txt, bno, btype = b
            t = txt.strip()
            if not t:
                continue
            if y1 < 60:
                tops.setdefault(t, []).append(i)
            if y0 > h - 60:
                bots.setdefault(t, []).append(i)
