    r"ICML|NeurIPS|NIPS|ICLR|ACL|EMNLP|NAACL|CVPR|ICCV|ECCV|AAAI|IJCAI|"
    r"SIGGRAPH|Interspeech|ICASSP|TASLP|AISTATS|KDD|WWW|SIGIR|UAI|COLT|JMLR)\b"
    r"[^\n\.]{0,120}", re.IGNORECASE)


