        return rects

    toks = stripped.split()
    for n in range(len(toks), 1, -1):
        for i in range(len(toks) - n + 1):
            sub = " ".join(toks[i:i + n])
            try:
                r = page.search_for(sub, quads=False)
            except Exception:
                r = []
            if r:
                _add(r)
                return rects
