    doc = fitz.open(src)
    orig_pages = len(doc)
    orig_text_len = sum(len(p.get_text()) for p in doc)
    literals = discover_identity(doc)
    ref_idx = find_references_page(doc)
    print(f"[{src.name}] {orig_pages} pages, references at page {ref_idx}, "
          f"{len(literals)} identity literals")
    for lit in sorted(literals):
        print(f"    LIT :: {lit!r}")

    for attempt in range(3):
        for i, pg in enumerate(doc):
            use_literals = (ref_idx is None) or (i < ref_idx)
            apply_redactions_page(pg, literals, IDENTIFIER_PATTERNS, use_literals)
        doc.set_metadata({})
        try:
            doc.set_xml_metadata("")
        except Exception:
            pass
        doc.save(dst, garbage=4, deflate=True, clean=True)
        doc.close()

        verify = fitz.open(dst)
        leaks = scan_leaks(verify, literals, IDENTIFIER_PATTERNS, ref_idx)
        if not leaks:
            assert len(verify) == orig_pages, "page count changed"
            retained = sum(len(p.get_text()) for p in verify) / max(orig_text_len, 1)
            print(f"[{src.name}] clean after iteration {attempt + 1}, "
                  f"text retained {retained:.1%}")
            verify.close()
            return
        print(f"[{src.name}] iteration {attempt + 1}: {len(leaks)} leaks remain")
        for p, k, m in leaks[:30]:
            print(f"    LEAK page {p} ({k}): {m!r}")
        doc = verify
    raise RuntimeError(f"{src.name}: leaks remain after 3 iterations")


def main():
    out = Path("/root/redacted")
    out.mkdir(parents=True, exist_ok=True)
    for n in (1, 2, 3):
        print("=" * 80)
        redact_pdf(Path(f"/root/paper{n}.pdf"), out / f"paper{n}.pdf")


if __name__ == "__main__":
    main()
