def rects_for_text(page, text):
    """Robustly locate all rects for `text` on `page`, trying variants and
    sub-token splits (handles multi-line / hyphenated matches)."""
    if not text:
        return []
    seen = set()
    rects = []

    def _add(rs):
        for r in rs:
            key = (round(r.x0, 1), round(r.y0, 1), round(r.x1, 1), round(r.y1, 1))
            if key not in seen:
                seen.add(key)
                rects.append(r)

    # 1. direct search
    try:
        _add(page.search_for(text, quads=False))
    except Exception:
        pass

    nv = norm_space(text)
    if nv and nv != text:
        try:
            _add(page.search_for(nv, quads=False))
        except Exception:
            pass

    stripped = text.strip(" .,:;()[]{}")
    if stripped and stripped != text:
        try:
            _add(page.search_for(stripped, quads=False))
        except Exception:
            pass

    if rects:
        return rects

    # 2. split on hyphens / slashes / whitespace to catch line-wrapped matches
