def norm_space(s: str) -> str:
    return re.sub(r"\s+", " ", s).strip()


def strip_marks(name: str) -> str:
    """Remove author-footnote markers (digits, *, ⋆, ∗, ♠, ♣, †, ‡, §, ¶, superscripts)."""
    # drop any non-letter/space/hyphen/apostrophe/quote char
    out = []
    for ch in name:
        cat = unicodedata.category(ch)
        if cat.startswith("L") or ch in " -'’\"“”.":
            out.append(ch)
    return norm_space("".join(out))


def split_authors(line: str):
    """Split an author line like 'A B1,2, C D3, and E F4' into individual names."""
    # replace ' and ' with comma
    s = re.sub(r"\s+and\s+", ", ", line, flags=re.IGNORECASE)
    parts = re.split(r"[,;]", s)
    names = []
    for p in parts:
        n = strip_marks(p)
        # must look like a name: at least two tokens, mostly letters, start with uppercase
        toks = n.split()
        if len(toks) >= 2 and all(t[0:1].isupper() or t[0:1] in "“\"'" for t in toks if t):
            names.append(n)
    return names


def split_affiliations(block: str):
    """Split an affiliation block into individual institution strings."""
    # Remove leading marker symbols/digits per entry
    # First replace common separators with newlines
    s = re.sub(r"[,;]\s*(?=\d|[♠♣♥♦†‡§¶*⋆∗])", "\n", block)
    out = set()
    for line in re.split(r"[\n]", s):
        line = line.strip()
        if not line:
            continue
        # strip leading marker
        line = re.sub(r"^[\d♠♣♥♦†‡§¶*⋆∗\s]+", "", line)
        line = line.strip(" ,;")
        if len(line) >= 4 and any(c.isalpha() for c in line):
            out.add(line)
    return out


# ---------------------------------------------------------------------------
# Discovery
# ---------------------------------------------------------------------------
def find_abstract_y(page):
    """Return y-coordinate where the 'Abstract' header begins, or None."""
    for b in page.get_text("blocks"):
        x0, y0, x1, y1, txt, bno, btype = b
        t = txt.strip().lower()
        if t == "abstract" or t.startswith("abstract\n") or t == "abstract.":
            return y0
    # fallback: search_for
    for word in ("Abstract", "ABSTRACT"):
        rs = page.search_for(word)
        if rs:
            return rs[0].y0
    return None


def discover_identity(doc):
    """Return (identity_literals, debug) discovered from this document."""
    literals = set()

    page1 = doc[0]
    abs_y = find_abstract_y(page1) or page1.rect.height * 0.3

    # --- title block: everything above Abstract (excluding the main title line)
    title_blocks = []
    for b in page1.get_text("blocks"):
        x0, y0, x1, y1, txt, bno, btype = b
        if y1 <= abs_y and txt.strip():
            title_blocks.append((y0, txt.strip()))
    title_blocks.sort()

    # Heuristic: first block is the title (keep), remainder = author/affiliation/correspondence
    for i, (y, t) in enumerate(title_blocks):
        if i == 0:
            # usually the title; skip
            continue
        # split lines
        for line in t.splitlines():
            line = line.strip()
            if not line:
                continue
            # whole raw line as a literal (useful for correspondence/affiliation lines)
            literals.add(line)
            # try to extract author names
            if any(ch.isdigit() or ch in "♠♣♥♦†‡§¶*⋆∗" for ch in line) or ("," in line and len(line.split()) <= 40):
                for name in split_authors(line):
                    literals.add(name)
            # affiliations
            for aff in split_affiliations(line):
                literals.add(aff)

    # --- also extract footnote / correspondence block near bottom of page 1
    # (equal contribution / affiliation / grant / venue footnote)
