def norm_space(s: str) -> str:
    return re.sub(r"\s+", " ", s).strip()


def strip_marks(name: str) -> str:
    out = []
    for ch in name:
        if ch in AUTHOR_MARK_CHARS or ch in SUPERSCRIPTS:
