# ---------------------------------------------------------------------------
# Redaction helpers
# ---------------------------------------------------------------------------
def rects_for_literal(page, literal):
    """Try several variants to locate rects for a literal in the page."""
    variants = [literal]
    # whitespace-normalized
    nv = norm_space(literal)
    if nv and nv != literal:
        variants.append(nv)
    # strip trailing punctuation
    stripped = literal.rstrip(" .,:;")
    if stripped and stripped != literal:
        variants.append(stripped)
    rects = []
    for v in variants:
        if not v:
            continue
        try:
            r = page.search_for(v, quads=False)
        except Exception:
            r = []
        if r:
            rects.extend(r)
            break
    # if multi-word and still nothing, try last-resort: longest token sequence
    if not rects and len(literal.split()) >= 3:
        toks = literal.split()
        for n in range(len(toks), 2, -1):
            for i in range(len(toks) - n + 1):
                sub = " ".join(toks[i:i + n])
                try:
                    r = page.search_for(sub, quads=False)
                except Exception:
                    r = []
                if r:
                    rects.extend(r)
                    return rects
    return rects


def find_references_page(doc):
    """Return (page_index, y) where References/Bibliography header begins, or (None, None)."""
    for i, pg in enumerate(doc):
        for header in ("References", "REFERENCES", "Bibliography", "BIBLIOGRAPHY"):
            # must be the section header, usually in top half or own block
            rs = pg.search_for(header)
            for r in rs:
                # heuristic: section headers tend to be left-aligned near column start
                # and not inside running text; accept the first hit
                return i, r.y0
    return None, None


def apply_redactions_page(page, literals, regexes, use_literals):
    text = page.get_text()
    added = 0

    if use_literals:
        for lit in literals:
            for rect in rects_for_literal(page, lit):
                page.add_redact_annot(rect, fill=(0, 0, 0))
                added += 1

    # regex matches: scan full text, then locate each match's rects
    for rx in regexes:
        for m in rx.finditer(text):
            match = m.group(0)
            rects = page.search_for(match, quads=False)
            if not rects:
                # try normalized / stripped variants
                for variant in (norm_space(match), match.rstrip(" .,);]")):
                    if variant and variant != match:
                        rects = page.search_for(variant, quads=False)
                        if rects:
                            break
            if not rects and len(match) > 10:
                # last resort: search for first half and second half
                mid = len(match) // 2
                for sub in (match[:mid], match[mid:]):
                    sub = sub.strip()
                    if len(sub) >= 6:
                        rects = page.search_for(sub, quads=False)
                        if rects:
                            break
            for r in rects:
                page.add_redact_annot(r, fill=(0, 0, 0))
                added += 1
    if added:
        page.apply_redactions()
    return added


def scan_leaks(doc, literals, regexes, ref_page_idx):
    """Return list of (page_idx, kind, match_text) for remaining hits."""
    leaks = []
    for i, pg in enumerate(doc):
        text = pg.get_text()
        for rx in regexes:
            for m in rx.finditer(text):
                leaks.append((i, "regex", m.group(0)))
        if ref_page_idx is None or i < ref_page_idx:
            for lit in literals:
                if lit and lit in text:
                    leaks.append((i, "literal", lit))
    return leaks


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def redact_pdf(src: Path, dst: Path):
    doc = fitz.open(src)
    literals = discover_identity(doc)
    ref_idx, _ = find_references_page(doc)
    print(f"[{src.name}] discovered {len(literals)} identity literals; "
          f"references starts at page {ref_idx}")
    for lit in sorted(literals):
        print(f"    LITERAL :: {lit!r}")

    # Up to 3 redact->scan iterations
    for attempt in range(3):
        for i, pg in enumerate(doc):
            use_literals = (ref_idx is None) or (i < ref_idx)
            apply_redactions_page(pg, literals, IDENTIFIER_PATTERNS, use_literals)

        # Clear metadata
        doc.set_metadata({})
        try:
            doc.set_xml_metadata("")
        except Exception:
            pass

        # Save to a temporary bytes buffer and reopen for scanning
        doc.save(dst, garbage=4, deflate=True, clean=True)
        doc.close()

        verify = fitz.open(dst)
        leaks = scan_leaks(verify, literals, IDENTIFIER_PATTERNS, ref_idx)
        if not leaks:
            print(f"[{src.name}] clean after iteration {attempt + 1}")
            # sanity: page count
            orig_pages = len(fitz.open(src))
            assert len(verify) == orig_pages, "page count changed"
            verify.close()
            return
        print(f"[{src.name}] iteration {attempt + 1}: {len(leaks)} leaks remain")
        for p, k, m in leaks[:20]:
            print(f"    LEAK page {p} ({k}): {m!r}")
        # continue redacting on the saved copy
        doc = verify
    raise RuntimeError(f"{src.name}: leaks remain after 3 iterations: {leaks[:10]}")


def main():
    out_dir = Path("/root/redacted")
    out_dir.mkdir(parents=True, exist_ok=True)
    for n in (1, 2, 3):
        src = Path(f"/root/paper{n}.pdf")
        dst = out_dir / f"paper{n}.pdf"
        print("=" * 80)
        redact_pdf(src, dst)
        print(f"wrote {dst}")


if __name__ == "__main__":
    main()
