def find_abstract_y(page):
    for b in page.get_text("blocks"):
        x0, y0, x1, y1, txt, bno, btype = b
        t = txt.strip().lower()
        if t == "abstract" or t.startswith("abstract\n") or t.startswith("a b s t r a c t"):
            return y0
    for word in ("Abstract", "ABSTRACT"):
        rs = page.search_for(word)
        if rs:
            return rs[0].y0
    return None


def is_author_block(text: str) -> bool:
    """Heuristic: text block containing author markers (digits/stars after names)."""
    # Must have at least 2 capitalized name-like tokens AND author markers nearby
    if not re.search(r"[A-Z][a-z]+\s+[A-Z][a-z]+", text):
        return False
    if re.search(rf"[A-Za-z][{re.escape(AUTHOR_MARK_CHARS)}]", text):
        return True
    if re.search(r"[A-Za-z]\d(?:[,\s]|$)", text):
        return True
    if re.search(r"\sand\s", text, flags=re.IGNORECASE) and "," in text:
        return True
    return False


def is_affiliation_block(text: str) -> bool:
    return any(kw in text for kw in AFFIL_KEYWORDS)


def is_footnote_block(text: str) -> bool:
    low = text.lower()
    if any(kw in low for kw in (
        "equal contribution", "corresponding author", "correspondence",
        "copyright", "supported by", "supported in part",
        "preprint", "under review", "to appear",
    )):
        return True
    if "@" in text:
        return True
    # starts with footnote marker
    if re.match(rf"^\s*[{re.escape(AUTHOR_MARK_CHARS)}]", text):
        return True
    # typical venue line
    if re.search(r"(workshop|conference|proceedings|arxiv|preprint)", low):
        return True
    return False


