    GENERIC = {"abstract", "preprint", "introduction", "equal contribution",
               "corresponding author", "the author", "the authors",
               "author", "authors"}
    cleaned = set()
    for lit in literals:
        s = lit.strip()
        if len(s) < 3:
            continue
