import re
import sys
import unicodedata
from pathlib import Path

import fitz  # PyMuPDF

# ---------------------------------------------------------------------------
# Identifier regexes (document-wide)
# ---------------------------------------------------------------------------
IDENTIFIER_PATTERNS = [
    # emails
    re.compile(r"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}"),
    # arXiv IDs (new scheme) with optional version
    re.compile(r"arXiv:\s*\d{4}\.\d{4,5}(?:v\d+)?", re.IGNORECASE),
    # arXiv URL
    re.compile(r"https?://(?:www\.)?arxiv\.org/\S+", re.IGNORECASE),
    # DOIs
    re.compile(r"10\.\d{4,9}/[^\s)]+"),
    # Common US grant / contract identifiers (NSF, ARO, DARPA, ONR, AFOSR, NIH)
    re.compile(r"\bNSF\s+[A-Z0-9\-]+", re.IGNORECASE),
    re.compile(r"\bARO\s+W\d{2,}[A-Z0-9\-]+", re.IGNORECASE),
    re.compile(r"\bDARPA\s+[A-Z0-9\-]+", re.IGNORECASE),
    re.compile(r"\bONR\s+N\d{2,}[A-Z0-9\-]+", re.IGNORECASE),
    re.compile(r"\bAFOSR\s+[A-Z0-9\-]+", re.IGNORECASE),
    re.compile(r"\bNIH\s+[A-Z0-9\-]+", re.IGNORECASE),
    # Grant/contract numbers like W911NF-23-2-0224 standalone
    re.compile(r"\bW\d{3,}[A-Z]{2}-\d+-\d+-\d+"),
]


def norm_space(s: str) -> str:
    return re.sub(r"\s+", " ", s).strip()


def strip_marks(name: str) -> str:
    """Remove author-footnote markers (digits, *, ⋆, ∗, ♠, ♣, †, ‡, §, ¶, superscripts)."""
    # drop any non-letter/space/hyphen/apostrophe/quote char
    out = []
    for ch in name:
        cat = unicodedata.category(ch)
        if cat.startswith("L") or ch in " -'’\"“”.":
            out.append(ch)
    return norm_space("".join(out))


def split_authors(line: str):
    """Split an author line like 'A B1,2, C D3, and E F4' into individual names."""
    # replace ' and ' with comma
    s = re.sub(r"\s+and\s+", ", ", line, flags=re.IGNORECASE)
    parts = re.split(r"[,;]", s)
    names = []
    for p in parts:
        n = strip_marks(p)
        # must look like a name: at least two tokens, mostly letters, start with uppercase
        toks = n.split()
        if len(toks) >= 2 and all(t[0:1].isupper() or t[0:1] in "“\"'" for t in toks if t):
            names.append(n)
    return names


def split_affiliations(block: str):
    """Split an affiliation block into individual institution strings."""
    # Remove leading marker symbols/digits per entry
    # First replace common separators with newlines
    s = re.sub(r"[,;]\s*(?=\d|[♠♣♥♦†‡§¶*⋆∗])", "\n", block)
    out = set()
    for line in re.split(r"[\n]", s):
        line = line.strip()
        if not line:
            continue
        # strip leading marker
        line = re.sub(r"^[\d♠♣♥♦†‡§¶*⋆∗\s]+", "", line)
        line = line.strip(" ,;")
        if len(line) >= 4 and any(c.isalpha() for c in line):
            out.add(line)
    return out


# ---------------------------------------------------------------------------
# Discovery
# ---------------------------------------------------------------------------
def find_abstract_y(page):
    """Return y-coordinate where the 'Abstract' header begins, or None."""
    for b in page.get_text("blocks"):
        x0, y0, x1, y1, txt, bno, btype = b
        t = txt.strip().lower()
        if t == "abstract" or t.startswith("abstract\n") or t == "abstract.":
            return y0
    # fallback: search_for
    for word in ("Abstract", "ABSTRACT"):
        rs = page.search_for(word)
        if rs:
            return rs[0].y0
    return None


def discover_identity(doc):
    """Return (identity_literals, debug) discovered from this document."""
    literals = set()

    page1 = doc[0]
    abs_y = find_abstract_y(page1) or page1.rect.height * 0.3

    # --- title block: everything above Abstract (excluding the main title line)
    title_blocks = []
    for b in page1.get_text("blocks"):
        x0, y0, x1, y1, txt, bno, btype = b
        if y1 <= abs_y and txt.strip():
            title_blocks.append((y0, txt.strip()))
    title_blocks.sort()

    # Heuristic: first block is the title (keep), remainder = author/affiliation/correspondence
    for i, (y, t) in enumerate(title_blocks):
        if i == 0:
            # usually the title; skip
            continue
        # split lines
        for line in t.splitlines():
            line = line.strip()
            if not line:
                continue
            # whole raw line as a literal (useful for correspondence/affiliation lines)
            literals.add(line)
            # try to extract author names
            if any(ch.isdigit() or ch in "♠♣♥♦†‡§¶*⋆∗" for ch in line) or ("," in line and len(line.split()) <= 40):
                for name in split_authors(line):
                    literals.add(name)
            # affiliations
            for aff in split_affiliations(line):
                literals.add(aff)

    # --- also extract footnote / correspondence block near bottom of page 1
    # (equal contribution / affiliation / grant / venue footnote)
    ph = page1.rect.height
    for b in page1.get_text("blocks"):
        x0, y0, x1, y1, txt, bno, btype = b
        if y0 > ph * 0.75 and txt.strip():
            for line in txt.splitlines():
                line = line.strip()
                if not line or line.isdigit():
                    continue
                literals.add(line)
                # also extract names if any
                for name in split_authors(line):
                    literals.add(name)
                for aff in split_affiliations(line):
                    literals.add(aff)

    # --- metadata author/subject/title fields
    md = doc.metadata or {}
    for key in ("author", "subject", "keywords"):
        v = md.get(key) or ""
        if not v:
            continue
        # author field may be semicolon- or comma-separated
        for part in re.split(r"[;,]", v):
            n = strip_marks(part)
            if len(n.split()) >= 2:
                literals.add(n)
        # also keep the whole string
        literals.add(v.strip())

    # --- repeated header/footer bands containing author-looking tokens
    tops, bots = {}, {}
    for i, pg in enumerate(doc):
        h = pg.rect.height
        for b in pg.get_text("blocks"):
            x0, y0, x1, y1, txt, bno, btype = b
            t = txt.strip()
            if not t:
                continue
            if y1 < 60:
                tops.setdefault(t, []).append(i)
            if y0 > h - 60:
                bots.setdefault(t, []).append(i)
    # Only add repeated header/footer strings if they look like identity leakage
    # (contain an email, affiliation keyword, or a known author name already in literals)
    def looks_identity(s):
        low = s.lower()
        if "@" in s or "university" in low or "institute" in low or "laboratory" in low:
            return True
        for lit in list(literals):
            if len(lit.split()) >= 2 and lit in s:
                return True
        return False

    for d in (tops, bots):
        for k, v in d.items():
            if len(v) >= 2 and looks_identity(k):
                literals.add(k)

    # --- cleanup literals: drop short / purely-numeric / punctuation-only
    cleaned = set()
    for lit in literals:
        s = lit.strip()
        if len(s) < 3:
            continue
        if s.isdigit():
            continue
        if not any(c.isalpha() for c in s):
            continue
        # drop generic single-word tokens (Abstract, Preprint, etc.) that aren't identity
        if s.lower() in {"abstract", "preprint", "introduction", "equal contribution",
                         "corresponding author", "corresponding author.", "* equal contribution",
                         "* equal contribution.", "*equal contribution", "⋆corresponding author."}:
            continue
        cleaned.add(s)
    return cleaned


# ---------------------------------------------------------------------------
# Redaction helpers
# ---------------------------------------------------------------------------
def rects_for_literal(page, literal):
    """Try several variants to locate rects for a literal in the page."""
    variants = [literal]
    # whitespace-normalized
    nv = norm_space(literal)
    if nv and nv != literal:
        variants.append(nv)
    # strip trailing punctuation
    stripped = literal.rstrip(" .,:;")
    if stripped and stripped != literal:
        variants.append(stripped)
    rects = []
    for v in variants:
        if not v:
            continue
        try:
            r = page.search_for(v, quads=False)
        except Exception:
            r = []
        if r:
            rects.extend(r)
            break
    # if multi-word and still nothing, try last-resort: longest token sequence
    if not rects and len(literal.split()) >= 3:
        toks = literal.split()
        for n in range(len(toks), 2, -1):
            for i in range(len(toks) - n + 1):
                sub = " ".join(toks[i:i + n])
                try:
                    r = page.search_for(sub, quads=False)
                except Exception:
                    r = []
                if r:
                    rects.extend(r)
                    return rects
    return rects


def find_references_page(doc):
    """Return (page_index, y) where References/Bibliography header begins, or (None, None)."""
    for i, pg in enumerate(doc):
        for header in ("References", "REFERENCES", "Bibliography", "BIBLIOGRAPHY"):
            # must be the section header, usually in top half or own block
            rs = pg.search_for(header)
            for r in rs:
                # heuristic: section headers tend to be left-aligned near column start
                # and not inside running text; accept the first hit
                return i, r.y0
    return None, None


def apply_redactions_page(page, literals, regexes, use_literals):
    text = page.get_text()
    added = 0

    if use_literals:
        for lit in literals:
            for rect in rects_for_literal(page, lit):
                page.add_redact_annot(rect, fill=(0, 0, 0))
                added += 1

    # regex matches: scan full text, then locate each match's rects
    for rx in regexes:
        for m in rx.finditer(text):
            match = m.group(0)
            rects = page.search_for(match, quads=False)
            if not rects:
                # try normalized / stripped variants
                for variant in (norm_space(match), match.rstrip(" .,);]")):
                    if variant and variant != match:
                        rects = page.search_for(variant, quads=False)
                        if rects:
                            break
            if not rects and len(match) > 10:
                # last resort: search for first half and second half
                mid = len(match) // 2
                for sub in (match[:mid], match[mid:]):
                    sub = sub.strip()
                    if len(sub) >= 6:
                        rects = page.search_for(sub, quads=False)
                        if rects:
                            break
            for r in rects:
                page.add_redact_annot(r, fill=(0, 0, 0))
                added += 1
    if added:
        page.apply_redactions()
    return added


def scan_leaks(doc, literals, regexes, ref_page_idx):
    """Return list of (page_idx, kind, match_text) for remaining hits."""
    leaks = []
    for i, pg in enumerate(doc):
        text = pg.get_text()
        for rx in regexes:
            for m in rx.finditer(text):
                leaks.append((i, "regex", m.group(0)))
        if ref_page_idx is None or i < ref_page_idx:
            for lit in literals:
                if lit and lit in text:
                    leaks.append((i, "literal", lit))
    return leaks


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def redact_pdf(src: Path, dst: Path):
    doc = fitz.open(src)
    literals = discover_identity(doc)
    ref_idx, _ = find_references_page(doc)
    print(f"[{src.name}] discovered {len(literals)} identity literals; "
          f"references starts at page {ref_idx}")
    for lit in sorted(literals):
        print(f"    LITERAL :: {lit!r}")

    # Up to 3 redact->scan iterations
    for attempt in range(3):
        for i, pg in enumerate(doc):
            use_literals = (ref_idx is None) or (i < ref_idx)
            apply_redactions_page(pg, literals, IDENTIFIER_PATTERNS, use_literals)

        # Clear metadata
        doc.set_metadata({})
        try:
            doc.set_xml_metadata("")
        except Exception:
            pass

        # Save to a temporary bytes buffer and reopen for scanning
        doc.save(dst, garbage=4, deflate=True, clean=True)
        doc.close()

        verify = fitz.open(dst)
        leaks = scan_leaks(verify, literals, IDENTIFIER_PATTERNS, ref_idx)
        if not leaks:
            print(f"[{src.name}] clean after iteration {attempt + 1}")
            # sanity: page count
            orig_pages = len(fitz.open(src))
            assert len(verify) == orig_pages, "page count changed"
            verify.close()
            return
        print(f"[{src.name}] iteration {attempt + 1}: {len(leaks)} leaks remain")
        for p, k, m in leaks[:20]:
            print(f"    LEAK page {p} ({k}): {m!r}")
        # continue redacting on the saved copy
        doc = verify
    raise RuntimeError(f"{src.name}: leaks remain after 3 iterations: {leaks[:10]}")


def main():
    out_dir = Path("/root/redacted")
    out_dir.mkdir(parents=True, exist_ok=True)
    for n in (1, 2, 3):
        src = Path(f"/root/paper{n}.pdf")
        dst = out_dir / f"paper{n}.pdf"
        print("=" * 80)
        redact_pdf(src, dst)
        print(f"wrote {dst}")


if __name__ == "__main__":
    main()
