def looks_like_name(tok: str) -> bool:
    """Heuristic: a candidate author name is 2-5 capitalized tokens."""
    parts = tok.split()
    if not (2 <= len(parts) <= 5):
        return False
    for p in parts:
        if not p:
            return False
        # middle initial like "P." allowed
        if re.fullmatch(r"[A-Z]\.", p):
            continue
