def norm_space(s: str) -> str:
    return re.sub(r"\s+", " ", s).strip()


def strip_marks(name: str) -> str:
    """Remove author-footnote markers (digits, *, ⋆, ∗, ♠, ♣, †, ‡, §, ¶, superscripts)."""
    # drop any non-letter/space/hyphen/apostrophe/quote char
    out = []
    for ch in name:
        cat = unicodedata.category(ch)
        if cat.startswith("L") or ch in " -'’\"“”.":
            out.append(ch)
    return norm_space("".join(out))


def split_authors(line: str):
    """Split an author line like 'A B1,2, C D3, and E F4' into individual names."""
    # replace ' and ' with comma
    s = re.sub(r"\s+and\s+", ", ", line, flags=re.IGNORECASE)
    parts = re.split(r"[,;]", s)
