import re
import sys
import unicodedata
from pathlib import Path

import fitz  # PyMuPDF

# ---------------------------------------------------------------------------
# Identifier regexes (document-wide)
# ---------------------------------------------------------------------------
IDENTIFIER_PATTERNS = [
    # emails
    re.compile(r"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}"),
    # arXiv IDs (new scheme) with optional version
    re.compile(r"arXiv:\s*\d{4}\.\d{4,5}(?:v\d+)?", re.IGNORECASE),
    # arXiv URL
    re.compile(r"https?://(?:www\.)?arxiv\.org/\S+", re.IGNORECASE),
    # DOIs
    re.compile(r"10\.\d{4,9}/[^\s)]+"),
    # Common US grant / contract identifiers (NSF, ARO, DARPA, ONR, AFOSR, NIH)
    re.compile(r"\bNSF\s+[A-Z0-9\-]+", re.IGNORECASE),
    re.compile(r"\bARO\s+W\d{2,}[A-Z0-9\-]+", re.IGNORECASE),
    re.compile(r"\bDARPA\s+[A-Z0-9\-]+", re.IGNORECASE),
    re.compile(r"\bONR\s+N\d{2,}[A-Z0-9\-]+", re.IGNORECASE),
    re.compile(r"\bAFOSR\s+[A-Z0-9\-]+", re.IGNORECASE),
    re.compile(r"\bNIH\s+[A-Z0-9\-]+", re.IGNORECASE),
    # Grant/contract numbers like W911NF-23-2-0224 standalone
    re.compile(r"\bW\d{3,}[A-Z]{2}-\d+-\d+-\d+"),
]


def norm_space(s: str) -> str:
    return re.sub(r"\s+", " ", s).strip()


def strip_marks(name: str) -> str:
    """Remove author-footnote markers (digits, *, ⋆, ∗, ♠, ♣, †, ‡, §, ¶, superscripts)."""
    # drop any non-letter/space/hyphen/apostrophe/quote char
    out = []
    for ch in name:
        cat = unicodedata.category(ch)
        if cat.startswith("L") or ch in " -'’\"“”.":
            out.append(ch)
    return norm_space("".join(out))


def split_authors(line: str):
    """Split an author line like 'A B1,2, C D3, and E F4' into individual names."""
    # replace ' and ' with comma
    s = re.sub(r"\s+and\s+", ", ", line, flags=re.IGNORECASE)
    parts = re.split(r"[,;]", s)
    names = []
    for p in parts:
        n = strip_marks(p)
        # must look like a name: at least two tokens, mostly letters, start with uppercase
        toks = n.split()
        if len(toks) >= 2 and all(t[0:1].isupper() or t[0:1] in "“\"'" for t in toks if t):
            names.append(n)
    return names


def split_affiliations(block: str):
    """Split an affiliation block into individual institution strings."""
    # Remove leading marker symbols/digits per entry
    # First replace common separators with newlines
    s = re.sub(r"[,;]\s*(?=\d|[♠♣♥♦†‡§¶*⋆∗])", "\n", block)
    out = set()
    for line in re.split(r"[\n]", s):
