def rects_for_text(page, text):
    if not text:
        return []
    seen = set()
    rects = []

    def _add(rs):
        for r in rs:
            key = (round(r.x0, 1), round(r.y0, 1), round(r.x1, 1), round(r.y1, 1))
            if key not in seen:
                seen.add(key)
                rects.append(r)

    try:
        _add(page.search_for(text, quads=False))
    except Exception:
        pass
    nv = norm_space(text)
    if nv and nv != text:
        try:
            _add(page.search_for(nv, quads=False))
        except Exception:
            pass
    stripped = text.strip(" .,:;()[]{}")
